describe('Filter list by multiple statuses', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual URL of the page
    });

    it('should filter the list by selected statuses successfully', () => {
        cy.get('[data-testid="status-filter"]').check(['status1', 'status2']); // Replace with actual status values
        cy.get('[data-testid="apply-filters"]').click();
        cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
        cy.get('[data-testid="list-item"]').each(($item) => {
            cy.wrap($item).should('contain.text', 'status1').or('contain.text', 'status2'); // Adjust based on expected content
        });
    });

    it('should show no results when no matching statuses are selected', () => {
        cy.get('[data-testid="status-filter"]').uncheck(['status1', 'status2']); // Uncheck all statuses
        cy.get('[data-testid="apply-filters"]').click();
        cy.get('[data-testid="no-results"]').should('be.visible'); // Adjust based on actual no results element
    });
});
